    {
        _haContext.CallService("ai_task", "generate_data", null, data);
    }

    ///<param name="taskName"> eg: home summary</param>
    ///<param name="instructions"> eg: Generate a funny notification that the garage door was left open</param>
    ///<param name="entityId"></param>
